function WidgetTypePicker({ dispatch }) {
  const [q, setQ] = useState('');
  const filtered = useMemo(() => {
    if (!q.trim()) return WIDGET_TYPES;
    const lc = q.toLowerCase();
    return WIDGET_TYPES.filter(wt =>
      wt.label.toLowerCase().includes(lc) || wt.type.toLowerCase().includes(lc)
    );
  }, [q]);

  return (
    <>
      <input
        className="input input-sm"
        style={{ width: '100%', marginBottom: 8 }}
        placeholder="Search chart types..."
        value={q}
        onChange={e => setQ(e.target.value)}
      />
      <div className="widget-type-grid">
        {filtered.map(wt => (
          <button
            key={wt.type}
            className="widget-type-btn"
            draggable
            onDragStart={e => {
              e.dataTransfer.setData('application/widget-type', wt.type);
              e.dataTransfer.setData('application/widget-label', wt.label);
              e.dataTransfer.effectAllowed = 'copy';
            }}
            onClick={() => dispatch({ type: 'ADD_WIDGET', payload: { type: wt.type, title: wt.label } })}
          >
            <span className="widget-type-btn-icon">{wt.icon}</span>
            {wt.label}
          </button>
        ))}
        {filtered.length === 0 && (
          <div style={{ padding: '8px 0', fontSize: 11, color: 'var(--text-muted)', textAlign: 'center', gridColumn: '1 / -1' }}>
            No chart types match
          </div>
        )}
      </div>
    </>
  );
}

// Custom resize handles with inline styles — bypasses library CSS specificity issues
const HANDLE_STYLES = {
  n:  { position: 'absolute', top: 0, left: 0, right: 0, height: 8, cursor: 'ns-resize', zIndex: 20 },
  ne: { position: 'absolute', top: 0, right: 0, width: 16, height: 16, cursor: 'ne-resize', zIndex: 20 },
  e:  { position: 'absolute', top: 0, right: 0, bottom: 0, width: 8, cursor: 'ew-resize', zIndex: 20 },
  se: { position: 'absolute', right: 0, bottom: 0, width: 16, height: 16, cursor: 'nwse-resize', zIndex: 20 },
  s:  { position: 'absolute', left: 0, right: 0, bottom: 0, height: 8, cursor: 'ns-resize', zIndex: 20 },
  sw: { position: 'absolute', bottom: 0, left: 0, width: 16, height: 16, cursor: 'nesw-resize', zIndex: 20 },
  w:  { position: 'absolute', top: 0, left: 0, bottom: 0, width: 8, cursor: 'ew-resize', zIndex: 20 },
  nw: { position: 'absolute', top: 0, left: 0, width: 16, height: 16, cursor: 'nwse-resize', zIndex: 20 },
};

const ResizeHandle = forwardRef(({ axis, ...rest }, ref) => (
  <div ref={ref} className={`rh rh-${axis}`} style={HANDLE_STYLES[axis] || {}} {...rest} />
));

// ── Dimensions Panel (dashboard-level hierarchic + cyclic dimensions) ────────
function DimensionsPanel({ dashboard, allColumns, dispatch }) {
  const hierarchies = dashboard.hierarchicDimensions || [];
  const cyclics = dashboard.cyclicDimensions || [];

  const updateHierarchies = (next) => dispatch({ type: 'SET_HIERARCHIC_DIMENSIONS', payload: next });
  const updateCyclics = (next) => dispatch({ type: 'SET_CYCLIC_DIMENSIONS', payload: next });

  const cardStyle = { border: '1px solid var(--border)', borderRadius: 4, padding: '8px 8px 6px', marginBottom: 6 };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      {/* ── Hierarchic ── */}
      <div>
        <div style={{ fontWeight: 600, fontSize: 12, marginBottom: 6, display: 'flex', alignItems: 'center', gap: 4 }}>
          <svg width="14" height="14" viewBox="0 0 14 14"><path d="M7 2L3 8h8zM7 12L3 6h8z" fill="currentColor" opacity="0.6"/></svg>
          Hierarchic
        </div>
        {hierarchies.map((hd, hi) => (
          <div key={hd.id} style={cardStyle}>
            <div style={{ display: 'flex', gap: 4, alignItems: 'center', marginBottom: 6 }}>
              <input className="input input-sm" style={{ flex: 1 }} placeholder="Name"
                value={hd.name || ''} onChange={e => {
                  const next = [...hierarchies];
                  next[hi] = { ...next[hi], name: e.target.value };
                  updateHierarchies(next);
                }} />
              <button className="btn btn-ghost btn-icon btn-sm" onClick={() => {
                updateHierarchies(hierarchies.filter((_, j) => j !== hi));
              }} title="Remove">{'\u2715'}</button>
            </div>
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 4 }}>Levels (top → bottom)</div>
            {(hd.levels || []).map((lvl, li) => (
              <div key={li} style={{ display: 'flex', gap: 4, alignItems: 'center', marginBottom: 3 }}>
                <span style={{ fontSize: 11, color: 'var(--text-muted)', width: 16, textAlign: 'center', flexShrink: 0 }}>{li + 1}</span>
                <select className="select select-sm" style={{ flex: 1 }} value={lvl || ''}
                  onChange={e => {
                    const next = [...hierarchies];
                    const levels = [...(next[hi].levels || [])];
                    levels[li] = e.target.value;
                    next[hi] = { ...next[hi], levels };
                    updateHierarchies(next);
                  }}>
                  <option value="">— select —</option>
                  {allColumns.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <button className="btn btn-ghost btn-icon btn-sm" disabled={li === 0} onClick={() => {
                  const next = [...hierarchies];
                  const levels = [...(next[hi].levels || [])];
                  [levels[li - 1], levels[li]] = [levels[li], levels[li - 1]];
                  next[hi] = { ...next[hi], levels };
                  updateHierarchies(next);
                }} title="Move up">{'\u2191'}</button>
                <button className="btn btn-ghost btn-icon btn-sm" onClick={() => {
                  const next = [...hierarchies];
                  const levels = (next[hi].levels || []).filter((_, j) => j !== li);
                  next[hi] = { ...next[hi], levels };
                  updateHierarchies(next);
                }}>{'\u2715'}</button>
              </div>
            ))}
            <button className="btn btn-ghost btn-sm" style={{ fontSize: 11 }} onClick={() => {
              const next = [...hierarchies];
              next[hi] = { ...next[hi], levels: [...(next[hi].levels || []), ''] };
              updateHierarchies(next);
            }}>+ Add level</button>
          </div>
        ))}
        <button className="btn btn-ghost btn-sm"
          onClick={() => updateHierarchies([...hierarchies, { id: uuid(), name: '', levels: ['', ''], currentLevel: 0, filters: [] }])}
        >+ New hierarchy</button>
      </div>

      {/* ── Cyclic ── */}
      <div>
        <div style={{ fontWeight: 600, fontSize: 12, marginBottom: 6, display: 'flex', alignItems: 'center', gap: 4 }}>
          <svg width="14" height="14" viewBox="0 0 14 14">
            <path d="M7 1a6 6 0 104.24 1.76" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
            <path d="M12 1v3h-3" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Cyclic
        </div>
        {cyclics.map((cd, ci) => (
          <div key={cd.id} style={cardStyle}>
            <div style={{ display: 'flex', gap: 4, alignItems: 'center', marginBottom: 6 }}>
              <input className="input input-sm" style={{ flex: 1 }} placeholder="Name"
                value={cd.name || ''} onChange={e => {
                  const next = [...cyclics];
                  next[ci] = { ...next[ci], name: e.target.value };
                  updateCyclics(next);
                }} />
              <button className="btn btn-ghost btn-icon btn-sm" onClick={() => {
                updateCyclics(cyclics.filter((_, j) => j !== ci));
              }} title="Remove">{'\u2715'}</button>
            </div>
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 4 }}>Interchangeable fields</div>
            {(cd.fields || []).map((fld, fi) => (
              <div key={fi} style={{ display: 'flex', gap: 4, alignItems: 'center', marginBottom: 3 }}>
                <select className="select select-sm" style={{ flex: 1 }} value={fld || ''}
                  onChange={e => {
                    const next = [...cyclics];
                    const fields = [...(next[ci].fields || [])];
                    fields[fi] = e.target.value;
                    next[ci] = { ...next[ci], fields };
                    updateCyclics(next);
                  }}>
                  <option value="">— select —</option>
                  {allColumns.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <button className="btn btn-ghost btn-icon btn-sm" onClick={() => {
                  const next = [...cyclics];
                  const fields = (next[ci].fields || []).filter((_, j) => j !== fi);
                  next[ci] = { ...next[ci], fields };
                  updateCyclics(next);
                }}>{'\u2715'}</button>
              </div>
            ))}
            <button className="btn btn-ghost btn-sm" style={{ fontSize: 11 }} onClick={() => {
              const next = [...cyclics];
              next[ci] = { ...next[ci], fields: [...(next[ci].fields || []), ''] };
              updateCyclics(next);
            }}>+ Add field</button>
          </div>
        ))}
        <button className="btn btn-ghost btn-sm"
          onClick={() => updateCyclics([...cyclics, { id: uuid(), name: '', fields: ['', ''], activeIndex: 0 }])}
        >+ New cycle</button>
      </div>
    </div>
  );
}

export default function DashboardBuilder() {
  const { state, dispatch } = useApp();
  const { dashboard, editingWidgetId } = state;
  const theme = dashboard.theme || {};
  const { isTablet } = useBreakpoint();

  // Sidebar collapse state (auto-collapse on tablet)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // Auto-collapse sidebar on tablet when editing a widget (editor takes priority)
  useEffect(() => {
    if (isTablet && !editingWidgetId) setSidebarCollapsed(true);
  }, [isTablet]); // eslint-disable-line react-hooks/exhaustive-deps

  // 24×12 grid: compute rowHeight so 12 rows fit the visible canvas height
  const canvasRef = useRef(null);
  const [rowHeight, setRowHeight] = useState(30);
  const cols = GRID_COLS;
  const rows = 12;
  const margin = 8;

  useEffect(() => {
    if (!canvasRef.current) return;
    const ro = new ResizeObserver(([entry]) => {
      const h = entry.contentRect.height;
      // rowHeight so that exactly `rows` rows fit: h = rows * rowHeight + (rows + 1) * margin
      const rh = (h - margin * (rows + 1)) / rows;
      setRowHeight(Math.max(10, Math.round(rh)));
    });
    ro.observe(canvasRef.current);
    return () => ro.disconnect();
  }, []);

  const currentPage = dashboard.pages.find(p => p.id === dashboard.currentPageId) || dashboard.pages[0];
  const layouts = useMemo(
    () => computeResponsiveLayouts(currentPage.layout),
    [currentPage.layout]
  );

  // ── Widget drag-to-page state ──
  const [draggingWidgetId, setDraggingWidgetId] = useState(null);
  const [dropTargetPageId, setDropTargetPageId] = useState(null);

  // ── Tab reorder state ──
  const [draggingTabId, setDraggingTabId] = useState(null);
  const [tabDropTargetId, setTabDropTargetId] = useState(null);

  const [editingPageName, setEditingPageName] = useState(null); // page id being renamed
  const [stylesOpen, setStylesOpen] = useState(false);
  const [dimsOpen, setDimsOpen] = useState(false);

  // Gather all columns from all datasets for dimension field dropdowns
  const allColumns = useMemo(() => {
    const seen = new Set();
    const cols = [];
    for (const ds of state.datasets) {
      for (const row of ds.data?.slice(0, 1) || []) {
        for (const key of Object.keys(row)) {
          if (!seen.has(key)) { seen.add(key); cols.push(key); }
        }
      }
    }
    return cols;
  }, [state.datasets]);

  const onLayoutChange = (_layout, allLayouts) => {
    dispatch({ type: 'UPDATE_LAYOUT', payload: allLayouts.lg || _layout });
  };

  const handleTypeReplace = useCallback((widgetId, newType, newLabel) => {
    const page = dashboard.pages.find(p => p.id === dashboard.currentPageId) || dashboard.pages[0];
    const widget = page?.widgets.find(w => w.id === widgetId);
    if (!widget) return;
    if (!canReplaceType(widget.type, newType, widget)) return;
    const oldLabel = WIDGET_TYPES.find(t => t.type === widget.type)?.label || widget.type;
    if (window.confirm(`Change "${widget.title}" from ${oldLabel} to ${newLabel}?\nData fields will be preserved.`)) {
      const fieldUpdates = mapFieldsForTypeChange(widget.type, newType, widget);
      dispatch({ type: 'UPDATE_WIDGET', payload: { id: widgetId, updates: fieldUpdates } });
    }
  }, [dashboard, dispatch]);

  // Compute grid background style
  const gridBgStyle = (() => {
    const period = rowHeight + margin;
    const offset = 16 + margin;
    return {
      backgroundImage: [
        'linear-gradient(rgba(255,255,255,.55) 1px, transparent 1px)',
        'linear-gradient(90deg, rgba(255,255,255,.55) 1px, transparent 1px)',
      ].join(', '),
      backgroundSize: `${period}px ${period}px`,
      backgroundPosition: `${offset}px ${offset}px`,
      background: theme.canvasColor || '#f0f4f8',
    };
  })();

  return (
    <div className="db-layout">
      {/* ── Left sidebar ── */}
      <div className={`db-sidebar ${isTablet && sidebarCollapsed ? 'db-sidebar--collapsed' : ''}`} style={{ position: 'relative' }}>
        {isTablet && (
          <button
            className="sidebar-toggle"
            onClick={() => setSidebarCollapsed(c => !c)}
            title={sidebarCollapsed ? 'Show sidebar' : 'Hide sidebar'}
          >
            {sidebarCollapsed ? '►' : '◄'}
          </button>
        )}
        {editingWidgetId
          ? <WidgetEditor widgetId={editingWidgetId} />
          : (
            <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
              <div className="db-sidebar-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontWeight: 600, fontSize: 13 }}>Dashboard</span>
                <button
                  className={`btn btn-sm ${state.renderPaused ? 'btn-primary' : 'btn-secondary'}`}
                  title={state.renderPaused ? 'Resume rendering (calculations are frozen)' : 'Pause rendering to avoid recalculations while editing'}
                  onClick={() => dispatch({ type: 'SET_RENDER_PAUSED', payload: !state.renderPaused })}
                  style={{ fontSize: 11 }}
                >
                  {state.renderPaused ? '▶ Resume' : '⏸ Pause'}
                </button>
              </div>
              <div className="db-sidebar-body">
                {/* ── Dashboard Styles Section ── */}
                <div style={{ marginBottom: 16 }}>
                  <div
                    style={{
                      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                      cursor: 'pointer', marginBottom: stylesOpen ? 10 : 0,
                    }}
                    onClick={() => setStylesOpen(o => !o)}
                  >
                    <div className="section-title" style={{ marginBottom: 0 }}>Dashboard Styles</div>
                    <span style={{ fontSize: 10, color: 'var(--text-light)' }}>{stylesOpen ? '▲' : '▼'}</span>
                  </div>

                  {stylesOpen && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                      <div className="form-group">
                        <label className="form-label">Font size — {theme.fontSize || 13}px</label>
                        <input
                          type="range" min={10} max={18} step={1}
                          value={theme.fontSize || 13}
                          onChange={e => dispatch({ type: 'SET_THEME', payload: { fontSize: parseInt(e.target.value) } })}
                        />
                      </div>

                      <div className="form-group">
                        <label className="form-label">Canvas background</label>
                        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                          <input
                            type="color"
                            value={theme.canvasColor || '#f0f4f8'}
                            onChange={e => dispatch({ type: 'SET_THEME', payload: { canvasColor: e.target.value } })}
                            style={{ width: 32, height: 28, border: '1px solid var(--border)', borderRadius: 4, cursor: 'pointer', padding: 2 }}
                          />
                          <input
                            className="input input-sm"
                            value={theme.canvasColor || '#f0f4f8'}
                            onChange={e => dispatch({ type: 'SET_THEME', payload: { canvasColor: e.target.value } })}
                            style={{ flex: 1 }}
                          />
                        </div>
                      </div>

                      <div className="form-group">
                        <label className="form-label">Default card color</label>
                        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                          <input
                            type="color"
                            value={theme.cardColor || '#ffffff'}
                            onChange={e => dispatch({ type: 'SET_THEME', payload: { cardColor: e.target.value } })}
                            style={{ width: 32, height: 28, border: '1px solid var(--border)', borderRadius: 4, cursor: 'pointer', padding: 2 }}
                          />
                          <input
                            className="input input-sm"
                            value={theme.cardColor || '#ffffff'}
                            onChange={e => dispatch({ type: 'SET_THEME', payload: { cardColor: e.target.value } })}
                            style={{ flex: 1 }}
                          />
                        </div>
                      </div>

                      <div className="form-group">
                        <label className="form-label">Border radius — {theme.cardRadius ?? 8}px</label>
                        <input
                          type="range" min={0} max={20} step={1}
                          value={theme.cardRadius ?? 8}
                          onChange={e => dispatch({ type: 'SET_THEME', payload: { cardRadius: parseInt(e.target.value) } })}
                        />
                      </div>

                      <div className="form-group">
                        <label className="form-label">Card shadow</label>
                        <select
                          className="select select-sm"
                          value={theme.cardShadow || 'md'}
                          onChange={e => dispatch({ type: 'SET_THEME', payload: { cardShadow: e.target.value } })}
                        >
                          <option value="none">None</option>
                          <option value="sm">Small</option>
                          <option value="md">Medium</option>
                          <option value="lg">Large</option>
                        </select>
                      </div>

                      <div className="form-group">
                        <label className="form-label">Color scheme</label>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                          {Object.keys(ALL_SCHEMES).map(key => (
                            <div
                              key={key}
                              className={`color-scheme-option ${(theme.colorScheme || 'vivid') === key ? 'color-scheme-option--active' : ''}`}
                              onClick={() => dispatch({ type: 'SET_THEME', payload: { colorScheme: key } })}
                            >
                              <div className="color-swatches">
                                {getSwatchColors(key).slice(0, 8).map((c, i) => (
                                  <div key={i} className="color-swatch" style={{ background: c }} />
                                ))}
                              </div>
                              <span style={{ fontSize: 12, textTransform: 'capitalize' }}>{key}</span>
                            </div>
                          ))}
                        </div>
                      </div>

                      <div className="form-group">
                        <label className="checkbox-row" style={{ cursor: 'pointer' }}>
                          <input
                            type="checkbox"
                            checked={dashboard.advancedStats || false}
                            onChange={e => dispatch({ type: 'SET_THEME', payload: { __advancedStats: e.target.checked } })}
                          />
                          Advanced statistics
                        </label>
                        <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2 }}>
                          Enables geometric/harmonic means, skewness, kurtosis, moments, fractiles, formula editor, and more.
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* ── Dimensions Section ── */}
                <div style={{ marginBottom: 16 }}>
                  <div
                    style={{
                      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                      cursor: 'pointer', marginBottom: dimsOpen ? 10 : 0,
                    }}
                    onClick={() => setDimsOpen(o => !o)}
                  >
                    <div className="section-title" style={{ marginBottom: 0 }}>
                      Dimensions
                      {((dashboard.hierarchicDimensions?.length || 0) + (dashboard.cyclicDimensions?.length || 0)) > 0 && (
                        <span className="badge badge-purple" style={{ marginLeft: 6 }}>
                          {(dashboard.hierarchicDimensions?.length || 0) + (dashboard.cyclicDimensions?.length || 0)}
                        </span>
                      )}
                    </div>
                    <span style={{ fontSize: 10, color: 'var(--text-light)' }}>{dimsOpen ? '▲' : '▼'}</span>
                  </div>

                  {dimsOpen && (
                    <DimensionsPanel
                      dashboard={dashboard}
                      allColumns={allColumns}
                      dispatch={dispatch}
                    />
                  )}
                </div>

                <hr className="divider" />

                <div className="section-title">Chart types</div>
                <WidgetTypePicker dispatch={dispatch} />

                {currentPage.widgets.length > 0 && (
                  <>
                    <hr className="divider" />
                    <div className="section-title">Widgets on this page</div>
                    {currentPage.widgets.map(w => (
                      <div
                        key={w.id}
                        style={{
                          display: 'flex', alignItems: 'center', gap: 8,
                          padding: '6px 8px', borderRadius: 'var(--radius)',
                          cursor: 'pointer',
                          background: editingWidgetId === w.id ? '#eff6ff' : 'transparent',
                          border: `1px solid ${editingWidgetId === w.id ? '#bfdbfe' : 'transparent'}`,
                        }}
                        onClick={() => dispatch({ type: 'SET_EDITING_WIDGET', payload: w.id })}
                      >
                        <span>{WIDGET_TYPES.find(t => t.type === w.type)?.icon || '📊'}</span>
                        <span style={{ flex: 1, fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {w.title}
                        </span>
                        <button
                          className="btn btn-ghost btn-icon btn-sm"
                          onClick={e => { e.stopPropagation(); dispatch({ type: 'REMOVE_WIDGET', payload: w.id }); }}
                        >✕</button>
                      </div>
                    ))}
                  </>
                )}
              </div>
            </div>
          )
        }
      </div>

      {/* ── Canvas + page tabs ── */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div
          className="db-canvas"
          ref={canvasRef}
          style={gridBgStyle}
          onDragOver={e => {
            if (e.dataTransfer.types.includes('application/widget-type')) {
              e.preventDefault();
              e.dataTransfer.dropEffect = 'copy';
            }
          }}
          onDrop={e => {
            const wType = e.dataTransfer.getData('application/widget-type');
            if (wType) {
              e.preventDefault();
              const wLabel = e.dataTransfer.getData('application/widget-label') || wType;
              dispatch({ type: 'ADD_WIDGET', payload: { type: wType, title: wLabel } });
            }
          }}
        >
          {currentPage.widgets.length === 0 ? (
            <div className="empty-state" style={{ height: '100%' }}>
              <div className="empty-state-icon">🎨</div>
              <h3>Empty page</h3>
              <p>Add a chart from the left sidebar to start building.</p>
            </div>
          ) : (
            <ResponsiveGrid
              className="layout"
              layouts={layouts}
              breakpoints={BREAKPOINTS}
              cols={COLS}
              rowHeight={rowHeight}
              draggableHandle=".widget-header"
              resizeHandles={['n', 'ne', 'e', 'se', 's', 'sw', 'w', 'nw']}
              resizeHandle={(axis, ref) => <ResizeHandle axis={axis} ref={ref} />}
              onLayoutChange={onLayoutChange}
              margin={[margin, margin]}
              compactType={null}
              preventCollision={true}
            >
              {currentPage.widgets.map(widget => (
                <div key={widget.id} style={{ height: '100%' }}>
                  <WidgetContainer
                    widget={widget}
                    isEditing={true}
                    isSelected={editingWidgetId === widget.id}
                    onSelect={() => dispatch({ type: 'SET_EDITING_WIDGET', payload: widget.id })}
                    onRemove={() => dispatch({ type: 'REMOVE_WIDGET', payload: widget.id })}
                    onDuplicate={() => dispatch({ type: 'DUPLICATE_WIDGET', payload: widget.id })}
                    onDragToPage={setDraggingWidgetId}
                    onTypeReplace={(newType, newLabel) => handleTypeReplace(widget.id, newType, newLabel)}
                  />
                </div>
              ))}
            </ResponsiveGrid>
          )}
        </div>

        {/* ── Page tabs ── */}
        <div className="page-tabs">
          {dashboard.pages.map(page => (
            <div
              key={page.id}
              draggable={editingPageName !== page.id}
              className={`page-tab ${page.id === dashboard.currentPageId ? 'page-tab--active' : ''} ${dropTargetPageId === page.id ? 'page-tab--drop-target' : ''} ${tabDropTargetId === page.id && draggingTabId !== page.id ? 'page-tab--reorder-target' : ''}`}
              onClick={() => dispatch({ type: 'SET_CURRENT_PAGE', payload: page.id })}
              onDoubleClick={() => setEditingPageName(page.id)}
              onDragStart={e => {
                e.dataTransfer.setData('application/page-id', page.id);
                e.dataTransfer.effectAllowed = 'move';
                setDraggingTabId(page.id);
              }}
              onDragEnd={() => { setDraggingTabId(null); setTabDropTargetId(null); }}
              onDragOver={e => {
                const isTab = e.dataTransfer.types.includes('application/page-id');
                const isWidget = draggingWidgetId || e.dataTransfer.types.includes('application/widget-id');
                if (isTab && draggingTabId && draggingTabId !== page.id) {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = 'move';
                  setTabDropTargetId(page.id);
                } else if (isWidget && page.id !== dashboard.currentPageId) {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = e.shiftKey ? 'copy' : 'move';
                  setDropTargetPageId(page.id);
                }
              }}
              onDragLeave={e => {
                if (!e.currentTarget.contains(e.relatedTarget)) {
                  setDropTargetPageId(null);
                  setTabDropTargetId(null);
                }
              }}
              onDrop={e => {
                e.preventDefault();
                const droppedTabId = e.dataTransfer.getData('application/page-id');
                if (droppedTabId && droppedTabId !== page.id) {
                  dispatch({ type: 'REORDER_PAGE', payload: { fromId: droppedTabId, toId: page.id } });
                  setDraggingTabId(null);
                  setTabDropTargetId(null);
                  return;
                }
                const widgetId = e.dataTransfer.getData('application/widget-id') || draggingWidgetId;
                if (widgetId && page.id !== dashboard.currentPageId) {
                  dispatch({
                    type: 'MOVE_WIDGET_TO_PAGE',
                    payload: { widgetId, targetPageId: page.id, copy: e.shiftKey },
                  });
                }
                setDraggingWidgetId(null);
                setDropTargetPageId(null);
              }}
            >
              {editingPageName === page.id ? (
                <input
                  className="page-tab-input"
                  autoFocus
                  defaultValue={page.name}
                  onBlur={e => {
                    dispatch({ type: 'RENAME_PAGE', payload: { id: page.id, name: e.target.value || page.name } });
                    setEditingPageName(null);
                  }}
                  onKeyDown={e => {
                    if (e.key === 'Enter') e.target.blur();
                    if (e.key === 'Escape') setEditingPageName(null);
                  }}
                  onClick={e => e.stopPropagation()}
                />
              ) : (
                <span>{page.name}</span>
              )}
              {dashboard.pages.length > 1 && (
                <button
                  className="page-tab-close"
                  onClick={e => { e.stopPropagation(); dispatch({ type: 'REMOVE_PAGE', payload: page.id }); }}
                >×</button>
              )}
            </div>
          ))}
          <button
            className="page-tab-add"
            onClick={() => dispatch({ type: 'ADD_PAGE' })}
            title="Add page"
          >+</button>
        </div>
      </div>
    </div>
  );
}
